RRB.load({"id": "ntpc-full-4", "exam": "ntpc", "label": "NTPC UG full mock 4 (100 Q)", "questions": [{"s": "General Awareness", "t": "Geography", "q": "Which pass on the Manali–Leh road was bypassed by the Atal Tunnel?", "o": ["Zoji La", "Nathu La", "Rohtang Pass", "Lipulekh"], "a": 2, "e": "The Atal Tunnel (opened 2020) under the Pir Panjal range bypasses the Rohtang Pass, linking Manali with Lahaul-Spiti all year.", "qh": "मनाली–लेह मार्ग पर किस दर्रे को अटल सुरंग ने बायपास कर दिया?", "oh": ["ज़ोजी ला", "नाथू ला", "रोहतांग दर्रा", "लिपुलेख"], "eh": "पीर पंजाल के नीचे बनी अटल सुरंग (2020) रोहतांग दर्रे को बायपास करके मनाली को साल भर लाहौल-स्पीति से जोड़ती है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The Lead Bank Scheme, under which one bank leads credit planning in each district, was introduced in which year?", "o": ["1975", "1982", "1969", "1991"], "a": 2, "e": "The Lead Bank Scheme began in December 1969, on the lines suggested by the Gadgil Study Group and the Nariman Committee.", "qh": "लीड बैंक योजना, जिसमें हर ज़िले में एक बैंक कर्ज़ की योजना की अगुवाई करता है, किस साल शुरू हुई?", "oh": ["1975", "1982", "1969", "1991"], "eh": "लीड बैंक योजना दिसंबर 1969 में गाडगिल अध्ययन समूह और नरीमन समिति के सुझाव पर शुरू हुई।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The fiscal deficit of the government is:", "o": ["Revenue expenditure minus revenue receipts", "Total expenditure minus total receipts other than borrowings", "Total imports minus total exports", "Total borrowings minus interest payments"], "a": 1, "e": "Fiscal deficit = total expenditure − (revenue receipts + non-debt capital receipts); it shows how much the government must borrow.", "qh": "सरकार का राजकोषीय घाटा (फ़िस्कल डेफ़िसिट) क्या होता है?", "oh": ["राजस्व खर्च में से राजस्व प्राप्तियाँ घटाने पर", "कुल खर्च में से उधार के अलावा कुल प्राप्तियाँ घटाने पर बचा हिस्सा", "कुल आयात में से कुल निर्यात घटाने पर", "कुल उधार में से ब्याज भुगतान घटाने पर"], "eh": "राजकोषीय घाटा = कुल खर्च − (राजस्व प्राप्तियाँ + बिना कर्ज़ वाली पूँजी प्राप्तियाँ); इससे पता चलता है कि सरकार को कितना उधार लेना होगा।", "level": "tough"}, {"s": "General Awareness", "t": "Computer", "q": "Which key deletes the character to the left of the cursor?", "o": ["Delete", "Backspace", "Shift", "Tab"], "a": 1, "e": "Backspace removes the character before (left of) the cursor; Delete removes the one after it.", "qh": "कर्सर के बाईं ओर वाला अक्षर कौन-सी कुंजी मिटाती है?", "oh": ["डिलीट", "बैकस्पेस", "शिफ़्ट", "टैब"], "eh": "बैकस्पेस कर्सर से पहले (बाईं ओर) वाला अक्षर मिटाता है; डिलीट उसके बाद वाला।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "Which tax replaced many indirect taxes in India from 1 July 2017?", "o": ["Value Added Tax (VAT)", "Income Tax", "Wealth Tax", "Goods and Services Tax (GST)"], "a": 3, "e": "GST, introduced through the 101st Amendment, subsumed excise, service tax, VAT and others from 1 July 2017.", "qh": "1 जुलाई 2017 से भारत में कई अप्रत्यक्ष करों की जगह कौन-सा कर आया?", "oh": ["मूल्य वर्धित कर (VAT)", "आयकर", "संपत्ति कर", "वस्तु एवं सेवा कर (GST)"], "eh": "101वें संशोधन से आया GST, 1 जुलाई 2017 से उत्पाद शुल्क, सेवा कर, VAT जैसे करों की जगह लागू हुआ।", "level": "easy"}, {"s": "General Awareness", "t": "General Science", "q": "Which vitamin is made in our skin when it is exposed to sunlight?", "o": ["Vitamin A", "Vitamin D", "Vitamin C", "Vitamin B12"], "a": 1, "e": "Ultraviolet-B rays in sunlight help the skin make vitamin D.", "qh": "धूप लगने पर हमारी त्वचा में कौन-सा विटामिन बनता है?", "oh": ["विटामिन A", "विटामिन D", "विटामिन C", "विटामिन B12"], "eh": "धूप की पराबैंगनी-B किरणों से त्वचा विटामिन D बनाती है।", "level": "easy"}, {"s": "General Awareness", "t": "Sports", "q": "How many players of a kho-kho team are on the field at a time?", "o": ["9", "7", "11", "6"], "a": 0, "e": "A kho-kho team has 12 players, of whom 9 take the field (8 sit in the central lane, 1 chases).", "qh": "खो-खो की एक टीम के कितने खिलाड़ी एक समय में मैदान पर होते हैं?", "oh": ["9", "7", "11", "6"], "eh": "खो-खो टीम में 12 खिलाड़ी होते हैं, जिनमें से 9 मैदान पर उतरते हैं (8 बीच की लाइन में बैठते हैं, 1 पीछा करता है)।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Who founded the Servants of India Society in 1905?", "o": ["Bal Gangadhar Tilak", "Lala Lajpat Rai", "Dadabhai Naoroji", "Gopal Krishna Gokhale"], "a": 3, "e": "Gopal Krishna Gokhale founded the Servants of India Society in Pune in 1905 to train workers for national service.", "qh": "1905 में 'सर्वेंट्स ऑफ़ इंडिया सोसाइटी' की स्थापना किसने की?", "oh": ["बाल गंगाधर तिलक", "लाला लाजपत राय", "दादाभाई नौरोजी", "गोपाल कृष्ण गोखले"], "eh": "गोपाल कृष्ण गोखले ने 1905 में पुणे में देश सेवा के लिए कार्यकर्ता तैयार करने हेतु यह सोसाइटी बनाई।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "The Nobel Prize in Chemistry 2026 was awarded to Henri B. Kagan and Kenso Soai for work in which area?", "o": ["Lithium-ion batteries", "Metal-organic frameworks", "Non-linear effects and autocatalysis in asymmetric organic synthesis", "Protein structure prediction"], "a": 2, "e": "The 2026 Chemistry prize went to Kagan (France) and Soai (Japan) 'for the discovery of non-linear effects and autocatalysis in asymmetric organic synthesis'.", "qh": "रसायन विज्ञान का नोबेल पुरस्कार 2026 हेनरी बी. कागन और केन्सो सोआई को किस काम के लिए मिला?", "oh": ["लिथियम-आयन बैटरी", "मेटल-ऑर्गेनिक फ़्रेमवर्क", "असममित कार्बनिक संश्लेषण में नॉन-लीनियर प्रभाव और ऑटोकैटेलिसिस", "प्रोटीन की संरचना का अनुमान"], "eh": "2026 का रसायन नोबेल कागन (फ़्रांस) और सोआई (जापान) को असममित कार्बनिक संश्लेषण में नॉन-लीनियर प्रभाव और ऑटोकैटेलिसिस की खोज के लिए मिला।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "Rakhigarhi, one of the largest Harappan sites, is in which present-day state?", "o": ["Haryana", "Gujarat", "Punjab", "Rajasthan"], "a": 0, "e": "Rakhigarhi is in Hisar district, Haryana.", "qh": "हड़प्पा सभ्यता के सबसे बड़े स्थलों में से एक राखीगढ़ी आज किस राज्य में है?", "oh": ["हरियाणा", "गुजरात", "पंजाब", "राजस्थान"], "eh": "राखीगढ़ी हरियाणा के हिसार ज़िले में है।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "With the addition of Sukhna Wetland (Chandigarh) and Sauj Jheel (Uttar Pradesh) in October 2026, India's number of Ramsar sites became:", "o": ["91", "103", "85", "110"], "a": 1, "e": "The two new Wetlands of International Importance took India's total to 103 Ramsar sites.", "qh": "अक्टूबर 2026 में सुखना वेटलैंड (चंडीगढ़) और सौज झील (उत्तर प्रदेश) जुड़ने के बाद भारत में रामसर स्थलों की संख्या कितनी हो गई?", "oh": ["91", "103", "85", "110"], "eh": "इन दो नए अंतरराष्ट्रीय महत्व के वेटलैंड्स के साथ भारत में रामसर स्थल 103 हो गए।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Kuchipudi classical dance belongs to which state?", "o": ["Kerala", "Tamil Nadu", "Andhra Pradesh", "Odisha"], "a": 2, "e": "Kuchipudi is named after a village in Krishna district, Andhra Pradesh.", "qh": "कुचिपुड़ी शास्त्रीय नृत्य किस राज्य का है?", "oh": ["केरल", "तमिलनाडु", "आंध्र प्रदेश", "ओडिशा"], "eh": "कुचिपुड़ी का नाम आंध्र प्रदेश के कृष्णा ज़िले के एक गाँव से पड़ा है।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Arjuna Award is given for outstanding performance in:", "o": ["Literature", "Films", "Scientific research", "Sports"], "a": 3, "e": "The Arjuna Award (since 1961) is given by the Ministry of Youth Affairs and Sports to sportspersons.", "qh": "अर्जुन पुरस्कार किस क्षेत्र में शानदार प्रदर्शन के लिए दिया जाता है?", "oh": ["साहित्य", "फ़िल्म", "वैज्ञानिक शोध", "खेल"], "eh": "अर्जुन पुरस्कार (1961 से) युवा मामले और खेल मंत्रालय खिलाड़ियों को देता है।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "In which year was NABARD set up?", "o": ["1982", "1969", "1935", "1991"], "a": 0, "e": "NABARD was set up on 12 July 1982 on the recommendation of the Shivaraman Committee.", "qh": "नाबार्ड (NABARD) की स्थापना किस साल हुई?", "oh": ["1982", "1969", "1935", "1991"], "eh": "शिवरामन समिति की सिफ़ारिश पर नाबार्ड 12 जुलाई 1982 को बना।", "level": "tough"}, {"s": "General Awareness", "t": "Science & Tech", "q": "Which Indian mission was the first to soft-land near the Moon's south polar region?", "o": ["Chandrayaan-3", "Chandrayaan-2", "Mangalyaan", "Aditya-L1"], "a": 0, "e": "Chandrayaan-3's Vikram lander touched down near the lunar south pole on 23 August 2023, now observed as National Space Day.", "qh": "चाँद के दक्षिणी ध्रुव के पास सबसे पहले सॉफ़्ट लैंडिंग करने वाला भारतीय मिशन कौन-सा था?", "oh": ["चंद्रयान-3", "चंद्रयान-2", "मंगलयान", "आदित्य-L1"], "eh": "चंद्रयान-3 का विक्रम लैंडर 23 अगस्त 2023 को चाँद के दक्षिणी ध्रुव के पास उतरा; यह दिन अब राष्ट्रीय अंतरिक्ष दिवस है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Which metal is the best conductor of electricity?", "o": ["Copper", "Aluminium", "Iron", "Silver"], "a": 3, "e": "Silver conducts best; copper is used in wires because it is nearly as good and much cheaper.", "qh": "बिजली का सबसे अच्छा चालक कौन-सी धातु है?", "oh": ["ताँबा", "एल्युमिनियम", "लोहा", "चाँदी"], "eh": "चाँदी सबसे अच्छी चालक है; तारों में ताँबा लगता है क्योंकि वह लगभग उतना ही अच्छा और बहुत सस्ता है।", "level": "medium"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was sworn in as Prime Minister of Bangladesh on 17 February 2026 after his party's landslide election win?", "o": ["Muhammad Yunus", "Tarique Rahman", "Sheikh Hasina", "Mirza Fakhrul Islam Alamgir"], "a": 1, "e": "Tarique Rahman of the Bangladesh Nationalist Party (BNP) took oath as Prime Minister on 17 February 2026.", "qh": "17 फ़रवरी 2026 को अपनी पार्टी की बड़ी जीत के बाद बांग्लादेश के प्रधानमंत्री की शपथ किसने ली?", "oh": ["मुहम्मद यूनुस", "तारिक़ रहमान", "शेख़ हसीना", "मिर्ज़ा फ़ख़रुल इस्लाम आलमगीर"], "eh": "बांग्लादेश नेशनलिस्ट पार्टी (BNP) के तारिक़ रहमान ने 17 फ़रवरी 2026 को प्रधानमंत्री पद की शपथ ली।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Which river is known as the 'Sorrow of Bihar'?", "o": ["Gandak", "Son", "Kosi", "Damodar"], "a": 2, "e": "The Kosi often changes course and causes floods in Bihar; the Damodar was called the 'Sorrow of Bengal'.", "qh": "किस नदी को 'बिहार का शोक' कहा जाता है?", "oh": ["गंडक", "सोन", "कोसी", "दामोदर"], "eh": "कोसी बार-बार रास्ता बदलती है और बिहार में बाढ़ लाती है; दामोदर को 'बंगाल का शोक' कहा जाता था।", "level": "easy"}, {"s": "General Awareness", "t": "Static GK", "q": "Which is the national river of India?", "o": ["Yamuna", "Godavari", "Ganga", "Brahmaputra"], "a": 2, "e": "The Ganga was declared the national river in 2008.", "qh": "भारत की राष्ट्रीय नदी कौन-सी है?", "oh": ["यमुना", "गोदावरी", "गंगा", "ब्रह्मपुत्र"], "eh": "2008 में गंगा को राष्ट्रीय नदी घोषित किया गया।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "Who presides over a joint sitting of the two Houses of Parliament?", "o": ["The President", "The Vice-President", "The Prime Minister", "The Speaker of the Lok Sabha"], "a": 3, "e": "Under Article 108, the Speaker of the Lok Sabha presides over a joint sitting.", "qh": "संसद के दोनों सदनों की संयुक्त बैठक की अध्यक्षता कौन करता है?", "oh": ["राष्ट्रपति", "उपराष्ट्रपति", "प्रधानमंत्री", "लोकसभा अध्यक्ष (स्पीकर)"], "eh": "अनुच्छेद 108 के तहत संयुक्त बैठक की अध्यक्षता लोकसभा अध्यक्ष करते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "How many Fundamental Duties are listed in Article 51A of the Constitution at present?", "o": ["10", "11", "12", "9"], "a": 1, "e": "Ten duties were added by the 42nd Amendment (1976); the 11th (education of children 6–14) by the 86th Amendment (2002).", "qh": "संविधान के अनुच्छेद 51A में अभी कितने मौलिक कर्तव्य हैं?", "oh": ["10", "11", "12", "9"], "eh": "42वें संशोधन (1976) से 10 कर्तव्य जुड़े; 11वाँ (6–14 साल के बच्चों की पढ़ाई) 86वें संशोधन (2002) से जुड़ा।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "How many bits make one byte?", "o": ["8", "4", "16", "10"], "a": 0, "e": "A byte is a group of 8 bits.", "qh": "एक बाइट में कितने बिट होते हैं?", "oh": ["8", "4", "16", "10"], "eh": "एक बाइट 8 बिट का समूह होता है।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "The Battle of Haldighati (1576) was fought between Akbar's army and:", "o": ["Rana Sanga", "Shivaji", "Maharana Pratap", "Hemu"], "a": 2, "e": "At Haldighati in 1576, Maharana Pratap of Mewar fought the Mughal army led by Raja Man Singh.", "qh": "हल्दीघाटी की लड़ाई (1576) अकबर की सेना और किसके बीच हुई?", "oh": ["राणा सांगा", "शिवाजी", "महाराणा प्रताप", "हेमू"], "eh": "1576 में हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने राजा मान सिंह की अगुवाई वाली मुग़ल सेना से लड़ाई की।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "The Group of Monuments at Hampi, a UNESCO World Heritage Site, is in which state?", "o": ["Karnataka", "Andhra Pradesh", "Telangana", "Maharashtra"], "a": 0, "e": "Hampi, the capital of the Vijayanagara Empire, is in Vijayanagara district of Karnataka.", "qh": "यूनेस्को विश्व धरोहर हम्पी के स्मारक किस राज्य में हैं?", "oh": ["कर्नाटक", "आंध्र प्रदेश", "तेलंगाना", "महाराष्ट्र"], "eh": "विजयनगर साम्राज्य की राजधानी हम्पी कर्नाटक के विजयनगर ज़िले में है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The idea of 'judicial review' in the Indian Constitution was taken from the constitution of:", "o": ["United Kingdom", "Ireland", "United States of America", "Canada"], "a": 2, "e": "Judicial review, like the Fundamental Rights, was inspired by the US Constitution.", "qh": "भारतीय संविधान में 'न्यायिक समीक्षा' का विचार किस देश के संविधान से लिया गया?", "oh": ["ब्रिटेन", "आयरलैंड", "अमेरिका", "कनाडा"], "eh": "मौलिक अधिकारों की तरह न्यायिक समीक्षा भी अमेरिकी संविधान से प्रेरित है।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "Who won the FIDE Candidates Tournament 2026 to earn a World Championship match against D. Gukesh?", "o": ["Fabiano Caruana", "Javokhir Sindarov", "Hikaru Nakamura", "R. Praggnanandhaa"], "a": 1, "e": "Uzbekistan's Javokhir Sindarov won the 2026 Candidates unbeaten with 10/14 and will challenge world champion D. Gukesh.", "qh": "FIDE कैंडिडेट्स टूर्नामेंट 2026 जीतकर डी. गुकेश के ख़िलाफ़ विश्व चैंपियनशिप मुक़ाबले का हक़ किसने पाया?", "oh": ["फ़ाबियानो कारुआना", "जावोखिर सिंदारोव", "हिकारू नाकामुरा", "आर. प्रज्ञानानंद"], "eh": "उज़्बेकिस्तान के जावोखिर सिंदारोव ने बिना कोई बाज़ी हारे 10/14 अंकों के साथ कैंडिडेट्स 2026 जीता; अब वे विश्व चैंपियन डी. गुकेश को चुनौती देंगे।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "By which process can the President of India be removed from office?", "o": ["No-confidence motion in the Lok Sabha", "Recall by voters", "An order of the Supreme Court", "Impeachment by Parliament"], "a": 3, "e": "Article 61 provides for impeachment of the President by both Houses of Parliament for violation of the Constitution.", "qh": "भारत के राष्ट्रपति को किस प्रक्रिया से पद से हटाया जा सकता है?", "oh": ["लोकसभा में अविश्वास प्रस्ताव", "मतदाताओं द्वारा वापस बुलाना", "सुप्रीम कोर्ट का आदेश", "संसद द्वारा महाभियोग"], "eh": "अनुच्छेद 61 के तहत संविधान के उल्लंघन पर संसद के दोनों सदन राष्ट्रपति पर महाभियोग चला सकते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Deficiency of iodine in the diet causes:", "o": ["Goitre", "Rickets", "Scurvy", "Night blindness"], "a": 0, "e": "Iodine is needed for the thyroid hormone; its lack causes goitre (swelling of the thyroid).", "qh": "खाने में आयोडीन की कमी से कौन-सा रोग होता है?", "oh": ["घेंघा (गॉयटर)", "रिकेट्स", "स्कर्वी", "रतौंधी"], "eh": "थायरॉइड हार्मोन बनाने के लिए आयोडीन चाहिए; इसकी कमी से घेंघा (थायरॉइड में सूजन) होता है।", "level": "easy"}, {"s": "General Awareness", "t": "Railways", "q": "The Rail Wheel Factory of Indian Railways is located at:", "o": ["Perambur (Chennai)", "Yelahanka (Bengaluru)", "Kapurthala", "Varanasi"], "a": 1, "e": "The Rail Wheel Factory at Yelahanka, Bengaluru makes wheels and axles; ICF is at Perambur, RCF at Kapurthala.", "qh": "भारतीय रेल की रेल व्हील फ़ैक्टरी कहाँ है?", "oh": ["पेरम्बूर (चेन्नई)", "येलहंका (बेंगलुरु)", "कपूरथला", "वाराणसी"], "eh": "येलहंका (बेंगलुरु) की रेल व्हील फ़ैक्टरी पहिए और धुरे बनाती है; ICF पेरम्बूर में, RCF कपूरथला में है।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Which line marks the boundary between India and China in the eastern sector?", "o": ["Durand Line", "Radcliffe Line", "Line of Control", "McMahon Line"], "a": 3, "e": "The McMahon Line (1914) is the boundary in the eastern sector (Arunachal Pradesh). Durand = Afghanistan–Pakistan; Radcliffe = India–Pakistan/Bangladesh.", "qh": "पूर्वी क्षेत्र में भारत और चीन के बीच की सीमा किस रेखा से तय होती है?", "oh": ["डूरंड रेखा", "रेडक्लिफ़ रेखा", "नियंत्रण रेखा (LoC)", "मैकमोहन रेखा"], "eh": "मैकमोहन रेखा (1914) पूर्वी क्षेत्र (अरुणाचल प्रदेश) की सीमा है। डूरंड = अफ़ग़ानिस्तान–पाकिस्तान; रेडक्लिफ़ = भारत–पाकिस्तान/बांग्लादेश।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "Chilika, India's largest brackish-water lagoon, is in which state?", "o": ["Odisha", "Andhra Pradesh", "Tamil Nadu", "West Bengal"], "a": 0, "e": "Chilika Lake on the Odisha coast is the largest coastal lagoon in India and a Ramsar site.", "qh": "भारत का सबसे बड़ा खारे पानी का लैगून चिल्का किस राज्य में है?", "oh": ["ओडिशा", "आंध्र प्रदेश", "तमिलनाडु", "पश्चिम बंगाल"], "eh": "ओडिशा तट की चिल्का झील भारत का सबसे बड़ा तटीय लैगून और रामसर स्थल है।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "The Supreme Court (Number of Judges) Amendment Act, 2026 raised the number of Supreme Court judges (other than the Chief Justice of India) from 33 to:", "o": ["34", "35", "40", "37"], "a": 3, "e": "The Act, assented on 11 August 2026 (in force from 16 May 2026), replaced 'thirty-three' with 'thirty-seven', so the Court can have 37 judges plus the CJI.", "qh": "सुप्रीम कोर्ट (न्यायाधीशों की संख्या) संशोधन अधिनियम, 2026 ने सुप्रीम कोर्ट के जजों (मुख्य न्यायाधीश के अलावा) की संख्या 33 से बढ़ाकर कितनी की?", "oh": ["34", "35", "40", "37"], "eh": "11 अगस्त 2026 को मंज़ूर (16 मई 2026 से लागू) इस अधिनियम ने 'तैंतीस' की जगह 'सैंतीस' कर दिया, यानी मुख्य न्यायाधीश के अलावा 37 जज हो सकते हैं।", "level": "tough"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Where was the main national event of the International Day of Yoga 2026 (theme: 'Yoga for Healthy Ageing') held?", "o": ["Kolkata", "Visakhapatnam", "Srinagar", "Jabalpur"], "a": 0, "e": "PM Narendra Modi led the main event at Red Road, Kolkata on 21 June 2026; the theme was 'Yoga for Healthy Ageing'.", "qh": "अंतरराष्ट्रीय योग दिवस 2026 (थीम: 'स्वस्थ बुढ़ापे के लिए योग') का मुख्य राष्ट्रीय कार्यक्रम कहाँ हुआ?", "oh": ["कोलकाता", "विशाखापत्तनम", "श्रीनगर", "जबलपुर"], "eh": "21 जून 2026 को प्रधानमंत्री नरेंद्र मोदी ने कोलकाता के रेड रोड पर मुख्य कार्यक्रम की अगुवाई की; थीम थी 'स्वस्थ बुढ़ापे के लिए योग'।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which leader wrote 'Gita Rahasya' while imprisoned in Mandalay jail?", "o": ["Aurobindo Ghosh", "Bal Gangadhar Tilak", "Mahatma Gandhi", "V. D. Savarkar"], "a": 1, "e": "Tilak wrote Gita Rahasya during his imprisonment in Mandalay (Burma), 1908–1914.", "qh": "मांडले जेल में रहते हुए 'गीता रहस्य' किस नेता ने लिखी?", "oh": ["अरविंद घोष", "बाल गंगाधर तिलक", "महात्मा गांधी", "वी. डी. सावरकर"], "eh": "तिलक ने 1908–1914 में मांडले (बर्मा) की जेल में 'गीता रहस्य' लिखी।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "Who was the Viceroy of India when the Partition of Bengal was announced in 1905?", "o": ["Lord Curzon", "Lord Minto", "Lord Ripon", "Lord Hardinge"], "a": 0, "e": "Lord Curzon announced the Partition of Bengal in 1905; it was annulled in 1911.", "qh": "1905 में बंगाल विभाजन की घोषणा के समय भारत का वायसराय कौन था?", "oh": ["लॉर्ड कर्ज़न", "लॉर्ड मिंटो", "लॉर्ड रिपन", "लॉर्ड हार्डिंग"], "eh": "लॉर्ड कर्ज़न ने 1905 में बंगाल विभाजन की घोषणा की; 1911 में इसे रद्द किया गया।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "Which acid is present in an ant's sting?", "o": ["Acetic acid", "Formic acid", "Citric acid", "Lactic acid"], "a": 1, "e": "Ants inject formic acid (methanoic acid); applying a mild base like baking soda gives relief.", "qh": "चींटी के डंक में कौन-सा अम्ल होता है?", "oh": ["एसिटिक अम्ल", "फ़ॉर्मिक अम्ल", "साइट्रिक अम्ल", "लैक्टिक अम्ल"], "eh": "चींटी फ़ॉर्मिक (मेथेनोइक) अम्ल डालती है; खाने का सोडा जैसा हल्का क्षार लगाने से आराम मिलता है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which soil is best suited for growing cotton?", "o": ["Laterite soil", "Black soil", "Alluvial soil", "Sandy soil"], "a": 1, "e": "Black (regur) soil holds moisture well and is ideal for cotton, so it is also called black cotton soil.", "qh": "कपास उगाने के लिए सबसे अच्छी मिट्टी कौन-सी है?", "oh": ["लैटेराइट मिट्टी", "काली मिट्टी", "जलोढ़ मिट्टी", "रेतीली मिट्टी"], "eh": "काली (रेगुर) मिट्टी नमी अच्छी तरह रोकती है और कपास के लिए सबसे अच्छी है, इसलिए इसे काली कपास मिट्टी भी कहते हैं।", "level": "easy"}, {"s": "General Awareness", "t": "History", "q": "Who began the construction of the Qutub Minar in Delhi?", "o": ["Iltutmish", "Alauddin Khalji", "Balban", "Qutb-ud-din Aibak"], "a": 3, "e": "Qutb-ud-din Aibak started it around 1199; Iltutmish completed the upper storeys.", "qh": "दिल्ली में क़ुतुब मीनार का निर्माण किसने शुरू करवाया?", "oh": ["इल्तुतमिश", "अलाउद्दीन ख़िलजी", "बलबन", "क़ुतुबुद्दीन ऐबक"], "eh": "क़ुतुबुद्दीन ऐबक ने लगभग 1199 में इसे शुरू कराया; ऊपर की मंज़िलें इल्तुतमिश ने पूरी कराईं।", "level": "easy"}, {"s": "General Awareness", "t": "Awards", "q": "Which two Indian cricketers were conferred the Padma Shri in the Padma Awards 2026?", "o": ["Virat Kohli and Smriti Mandhana", "Jasprit Bumrah and Mithali Raj", "Rohit Sharma and Harmanpreet Kaur", "Ravindra Jadeja and Jhulan Goswami"], "a": 2, "e": "Rohit Sharma and Harmanpreet Kaur were among the sportspersons who received the Padma Shri in 2026.", "qh": "पद्म पुरस्कार 2026 में किन दो भारतीय क्रिकेटरों को पद्म श्री मिला?", "oh": ["विराट कोहली और स्मृति मंधाना", "जसप्रीत बुमराह और मिताली राज", "रोहित शर्मा और हरमनप्रीत कौर", "रवींद्र जडेजा और झूलन गोस्वामी"], "eh": "2026 में पद्म श्री पाने वाले खिलाड़ियों में रोहित शर्मा और हरमनप्रीत कौर शामिल थे।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Which Constitutional Amendment Act of 1992 gave constitutional status to Panchayati Raj institutions?", "o": ["74th Amendment", "42nd Amendment", "61st Amendment", "73rd Amendment"], "a": 3, "e": "The 73rd Amendment added Part IX (Panchayats); the 74th dealt with urban local bodies.", "qh": "1992 के किस संविधान संशोधन ने पंचायती राज संस्थाओं को संवैधानिक दर्जा दिया?", "oh": ["74वाँ संशोधन", "42वाँ संशोधन", "61वाँ संशोधन", "73वाँ संशोधन"], "eh": "73वें संशोधन से भाग IX (पंचायतें) जुड़ा; 74वाँ शहरी स्थानीय निकायों के बारे में है।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A car covers 135 km in 2 hours 15 minutes. What is its speed in metres per second?", "o": ["50/3 m/s", "100/3 m/s", "60 m/s", "65/3 m/s"], "a": 0, "e": "Speed = 135/2.25 = 60 km/h = 60 × 5/18 = 50/3 m/s.", "qh": "एक कार 135 km की दूरी 2 घंटे 15 मिनट में तय करती है। उसकी रफ़्तार मीटर प्रति सेकंड में कितनी है?", "oh": ["50/3 m/s", "100/3 m/s", "60 m/s", "65/3 m/s"], "eh": "रफ़्तार = 135/2.25 = 60 km/h = 60 × 5/18 = 50/3 m/s।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Suresh starts a business with ₹40,000. After 4 months, Ajay joins with ₹36,000. At the end of the year the profit is ₹4,000. What is Ajay's share?", "o": ["₹1,500", "₹2,500", "₹500", "₹2,000"], "a": 0, "e": "Capital × months = 40000×12 : 36000×8 = 5 : 3. Share = 3/8 × ₹4,000 = ₹1,500.", "qh": "सुरेश ₹40,000 से कारोबार शुरू करता है। 4 महीने बाद अजय ₹36,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹4,000 है। अजय का हिस्सा कितना है?", "oh": ["₹1,500", "₹2,500", "₹500", "₹2,000"], "eh": "पूँजी × महीने = 40000×12 : 36000×8 = 5 : 3। हिस्सा = 3/8 × ₹4,000 = ₹1,500।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "A sum of money at simple interest amounts to ₹6,875 in 3 years and to ₹8,125 in 5 years. What is the rate of interest per annum?", "o": ["15%", "12.5%", "100/11%", "13.5%"], "a": 1, "e": "Interest for 2 years = ₹1,250 → ₹625 per year. Principal = ₹6,875 − 3 × ₹625 = ₹5,000. Rate = ₹625/₹5,000 × 100 = 12.5%.", "qh": "साधारण ब्याज पर कोई रकम 3 साल में ₹6,875 और 5 साल में ₹8,125 हो जाती है। वार्षिक ब्याज दर क्या है?", "oh": ["15%", "12.5%", "100/11%", "13.5%"], "eh": "2 साल का ब्याज = ₹1,250 → हर साल ₹625। मूलधन = ₹6,875 − 3 × ₹625 = ₹5,000। दर = ₹625/₹5,000 × 100 = 12.5%।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A dishonest grocer uses a weight of 900 g in place of 1 kg but claims to sell at cost price. What is his gain percentage?", "o": ["11 1/9%", "10%", "12 1/9%", "10 1/9%"], "a": 0, "e": "He gives 900 g but charges for 1000 g: gain = 1000 × 1/900 − 1 = 11 1/9%.", "qh": "एक बेईमान दुकानदार 1 kg की जगह 900 g का बाट इस्तेमाल करता है पर दावा करता है कि वह क्रय मूल्य पर ही बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["11 1/9%", "10%", "12 1/9%", "10 1/9%"], "eh": "वह 900 g देता है पर 1000 g के पैसे लेता है: लाभ = 1000 × 1/900 − 1 = 11 1/9%।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Two mobile covers are sold for ₹2,400 each. On one there is a gain of 25% and on the other a loss of 25%. What is the overall gain or loss percentage?", "o": ["12.5% loss", "7.25% loss", "6.25% loss", "No profit, no loss"], "a": 2, "e": "When SP is the same and gain% = loss% = 25, there is always a loss of x²/100 = 625/100 = 6.25%.", "qh": "दो मोबाइल कवर ₹2,400 प्रत्येक में बेचे गए। एक पर 25% लाभ और दूसरे पर 25% हानि हुई। कुल मिलाकर कितने प्रतिशत लाभ या हानि हुई?", "oh": ["12.5% हानि", "7.25% हानि", "6.25% हानि", "न लाभ, न हानि"], "eh": "जब विक्रय मूल्य बराबर हो और लाभ% = हानि% = 25, तो हमेशा x²/100 = 625/100 = 6.25% हानि होती है।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "How many numbers from 1 to 500 are divisible by both 4 and 6?", "o": ["82", "43", "42", "41"], "a": 3, "e": "Divisible by both = divisible by LCM 12: ⌊500/12⌋ − ⌊0/12⌋ = 41.", "qh": "1 से 500 तक कितनी संख्याएँ 4 और 6 दोनों से विभाज्य हैं?", "oh": ["82", "43", "42", "41"], "eh": "दोनों से विभाज्य = LCM से विभाज्य 12: ⌊500/12⌋ − ⌊0/12⌋ = 41।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "The difference between compound interest and simple interest on a sum for 3 years at 20% per annum is ₹2,048. What is the sum?", "o": ["₹16,000", "₹10,240", "₹15,000", "₹18,000"], "a": 0, "e": "CI − SI = P[(1 + 20/100)^3 − 1 − 3 × 20/100] = 16/125 × P = ₹2,048 → P = ₹16,000.", "qh": "किसी रकम पर 20% वार्षिक दर से 3 साल के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹2,048 है। रकम कितनी है?", "oh": ["₹16,000", "₹10,240", "₹15,000", "₹18,000"], "eh": "CI − SI = P[(1 + 20/100)^3 − 1 − 3 × 20/100] = 16/125 × P = ₹2,048 → P = ₹16,000।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A train running at 36 km/h crosses a pole in 10 seconds. What is the length of the train?", "o": ["129.6 m", "100 m", "200 m", "150 m"], "a": 1, "e": "36 km/h = 36 × 5/18 = 10 m/s. Length = 10 × 10 = 100 m.", "qh": "36 km/h की रफ़्तार से चल रही एक ट्रेन एक खंभे को 10 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?", "oh": ["129.6 m", "100 m", "200 m", "150 m"], "eh": "36 km/h = 36 × 5/18 = 10 m/s। लंबाई = 10 × 10 = 100 m।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average weight of 20 persons increases by 5 kg when a person weighing 65 kg is replaced by a new person. What is the weight of the new person?", "o": ["160 kg", "70 kg", "165 kg", "185 kg"], "a": 2, "e": "Total increase = 20 × 5 = 100 kg. New = 65 + 100 = 165 kg.", "qh": "20 लोगों का औसत वज़न 5 kg बढ़ जाता है, जब 65 kg वज़न वाले एक व्यक्ति की जगह कोई नया व्यक्ति आता है। नए व्यक्ति का वज़न कितना है?", "oh": ["160 kg", "70 kg", "165 kg", "185 kg"], "eh": "कुल बढ़ोतरी = 20 × 5 = 100 kg। नया = 65 + 100 = 165 kg।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If x + 1/x = 7, what is the value of x³ + 1/x³?", "o": ["336", "364", "322", "343"], "a": 2, "e": "x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 343 − 21 = 322.", "qh": "अगर x + 1/x = 7 है, तो x³ + 1/x³ का मान क्या है?", "oh": ["336", "364", "322", "343"], "eh": "x³ + 1/x³ = (x + 1/x)³ − 3(x + 1/x) = 343 − 21 = 322।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper marks his goods 50% above the cost price and allows a discount of 15%. If he gains ₹330 on an article, what is its cost price?", "o": ["₹1,200", "₹1,530", "₹3,300", "₹1,300"], "a": 0, "e": "SP = CP × 1.5 × 0.85 = 51/40 × CP → profit = 27.5% of CP = ₹330 → CP = ₹1,200.", "qh": "एक दुकानदार सामान पर क्रय मूल्य से 50% ज़्यादा दाम लिखता है और 15% छूट देता है। अगर एक वस्तु पर उसे ₹330 लाभ होता है, तो उसका क्रय मूल्य क्या है?", "oh": ["₹1,200", "₹1,530", "₹3,300", "₹1,300"], "eh": "विक्रय मूल्य = क्रय मूल्य × 51/40 → लाभ = क्रय मूल्य का 27.5% = ₹330 → क्रय मूल्य = ₹1,200।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "If each edge of a cube is increased by 200%, by what percentage does its surface area increase?", "o": ["850%", "900%", "800%", "200%"], "a": 2, "e": "New area = 3² = 9 times → increase = (9 − 1) × 100 = 800%.", "qh": "अगर घन की हर भुजा 200% बढ़ा दी जाए, तो उसका पृष्ठीय क्षेत्रफल कितने प्रतिशत बढ़ेगा?", "oh": ["850%", "900%", "800%", "200%"], "eh": "नया क्षेत्रफल = 3² = 9 गुना → बढ़ोतरी = (9 − 1) × 100 = 800%।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "Find the value of (3^5 × 3^4) ÷ (3^4 × 9²).", "o": ["1", "4", "6", "3"], "a": 3, "e": "9² = 3^4. Power = 5 + 4 − 4 − 4 = 1 → 3^1 = 3.", "qh": "(3^5 × 3^4) ÷ (3^4 × 9²) का मान ज्ञात कीजिए।", "oh": ["1", "4", "6", "3"], "eh": "9² = 3^4. घात = 5 + 4 − 4 − 4 = 1 → 3^1 = 3।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "The price of an article is first increased by 50% and then decreased by 10%. What is the net percentage change in its price?", "o": ["35% increase", "40% increase", "35% decrease", "5% decrease"], "a": 0, "e": "Net factor = 1.5 × 0.9 = 1.35. Change = 35%.", "qh": "किसी वस्तु का दाम पहले 50% बढ़ाया जाता है और फिर 10% घटाया जाता है। दाम में कुल कितने प्रतिशत का बदलाव हुआ?", "oh": ["35% बढ़ोतरी", "40% बढ़ोतरी", "35% कमी", "5% कमी"], "eh": "कुल गुणक = 1.5 × 0.9 = 1.35। बदलाव = 35%।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average weight of 15 persons increases by 1 kg when a person weighing 65 kg is replaced by a new person. What is the weight of the new person?", "o": ["79 kg", "80 kg", "95 kg", "66 kg"], "a": 1, "e": "Total increase = 15 × 1 = 15 kg. New = 65 + 15 = 80 kg.", "qh": "15 लोगों का औसत वज़न 1 kg बढ़ जाता है, जब 65 kg वज़न वाले एक व्यक्ति की जगह कोई नया व्यक्ति आता है। नए व्यक्ति का वज़न कितना है?", "oh": ["79 kg", "80 kg", "95 kg", "66 kg"], "eh": "कुल बढ़ोतरी = 15 × 1 = 15 kg। नया = 65 + 15 = 80 kg।", "level": "medium"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Arjun and Ravi are in the ratio 2 : 3. After 8 years, the ratio will be 10 : 13. What is Ravi's present age?", "o": ["22 years", "10 years", "12 years", "18 years"], "a": 3, "e": "(2x + 8)/(3x + 8) = 10/13 → x = 6; age = 3 × 6 = 18 years.", "qh": "अर्जुन और रवि की अभी की आयु का अनुपात 2 : 3 है। 8 साल बाद यह अनुपात 10 : 13 हो जाएगा। रवि की अभी की आयु कितनी है?", "oh": ["22 साल", "10 साल", "12 साल", "18 साल"], "eh": "(2x + 8)/(3x + 8) = 10/13 → x = 6; आयु = 3 × 6 = 18 साल।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "Find the value of cos² 45° × tan² 30°.", "o": ["1/3", "-1/3", "1/6", "2/3"], "a": 2, "e": "Put standard values: cos² 45° = 1/2, tan² 30° = 1/3 → value = 1/6.", "qh": "cos² 45° × tan² 30° का मान ज्ञात कीजिए।", "oh": ["1/3", "-1/3", "1/6", "2/3"], "eh": "मानक मान रखें: cos² 45° = 1/2, tan² 30° = 1/3 → मान = 1/6।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "₹5,250 is divided among Naveen, Seema and Neha in the ratio 1 : 2 : 4. What is Naveen's share?", "o": ["₹1,500", "₹4,500", "₹3,000", "₹750"], "a": 3, "e": "Total parts = 7; one part = ₹5,250/7 = ₹750; share = 1 × ₹750 = ₹750.", "qh": "₹5,250 को नवीन, सीमा और नेहा में 1 : 2 : 4 के अनुपात में बाँटा गया। नवीन का हिस्सा कितना है?", "oh": ["₹1,500", "₹4,500", "₹3,000", "₹750"], "eh": "कुल भाग = 7; एक भाग = ₹5,250/7 = ₹750; हिस्सा = 1 × ₹750 = ₹750।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "The HCF of two numbers is 16 and their LCM is 1008. If one of the numbers is 112, what is the other number?", "o": ["63", "128", "160", "144"], "a": 3, "e": "Product of numbers = HCF × LCM → other = 16 × 1008/112 = 144.", "qh": "दो संख्याओं का HCF 16 और LCM 1008 है। अगर एक संख्या 112 है, तो दूसरी संख्या क्या है?", "oh": ["63", "128", "160", "144"], "eh": "संख्याओं का गुणनफल = HCF × LCM → दूसरी = 16 × 1008/112 = 144।", "level": "tough"}, {"s": "Mathematics", "t": "Geometry", "q": "The angles of a triangle are in the ratio 2 : 3 : 5. What is the largest angle?", "o": ["100°", "90°", "54°", "36°"], "a": 1, "e": "Sum of parts = 10; largest = 5/10 × 180° = 90°.", "qh": "एक त्रिभुज के कोणों का अनुपात 2 : 3 : 5 है। सबसे बड़ा कोण कितना है?", "oh": ["100°", "90°", "54°", "36°"], "eh": "भागों का योग = 10; सबसे बड़ा = 5/10 × 180° = 90°।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the greatest number that divides 479, 276 and 295, leaving remainders 3, 4 and 6 respectively?", "o": ["35", "21", "17", "19"], "a": 2, "e": "Subtract the remainders: 476, 272, 289. HCF = 17.", "qh": "वह सबसे बड़ी संख्या कौन-सी है जिससे 479, 276 और 295 को भाग देने पर क्रमशः 3, 4 और 6 शेष बचें?", "oh": ["35", "21", "17", "19"], "eh": "शेषफल घटाएँ: 476, 272, 289। HCF = 17।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the volume of a cone with radius 3.5 cm and height 12 cm? (Take π = 22/7)", "o": ["110 cm³", "176 cm³", "154 cm³", "308 cm³"], "a": 2, "e": "⅓πr²h = ⅓ × 22/7 × 3.5² × 12 = 154 cm³.", "qh": "3.5 cm त्रिज्या और ऊँचाई 12 cm वाले शंकु का आयतन कितना है? (π = 22/7 लें)", "oh": ["110 cm³", "176 cm³", "154 cm³", "308 cm³"], "eh": "⅓πr²h = ⅓ × 22/7 × 3.5² × 12 = 154 cm³।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "In an examination, a student who scores 25% marks fails by 105 marks, while another student who scores 48% marks gets 79 marks more than the pass marks. What are the maximum marks?", "o": ["800", "700", "850", "1000"], "a": 0, "e": "(48 − 25)% of maximum = 105 + 79 = 184 → maximum = 184 × 100/23 = 800.", "qh": "एक परीक्षा में 25% अंक पाने वाला छात्र 105 अंकों से फ़ेल होता है, जबकि 48% अंक पाने वाले छात्र को पास अंकों से 79 अंक ज़्यादा मिलते हैं। पूरे अंक कितने हैं?", "oh": ["800", "700", "850", "1000"], "eh": "पूरे अंकों का (48 − 25)% = 105 + 79 = 184 → पूरे अंक = 184 × 100/23 = 800।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "A and B together can do a piece of work in 10 days, B and C together in 15 days, and C and A together in 10 days. In how many days can A, B and C together finish it?", "o": ["30 days", "15 days", "7.5 days", "9.5 days"], "a": 2, "e": "2(A + B + C) = 1/10 + 1/15 + 1/10 → A + B + C = 1/7.5 per day → 7.5 days.", "qh": "A और B मिलकर एक काम 10 दिन में, B और C मिलकर 15 दिन में, और C और A मिलकर 10 दिन में कर सकते हैं। A, B और C तीनों मिलकर वह काम कितने दिन में करेंगे?", "oh": ["30 दिन", "15 दिन", "7.5 दिन", "9.5 दिन"], "eh": "2(A + B + C) = 1/10 + 1/15 + 1/10 → A + B + C = 1/7.5 प्रति दिन → 7.5 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If a + b = 16 and ab = 60, what is a² + b²?", "o": ["136", "196", "140", "256"], "a": 0, "e": "a² + b² = (a + b)² − 2ab = 256 − 120 = 136.", "qh": "अगर a + b = 16 और ab = 60 है, तो a² + b² का मान क्या है?", "oh": ["136", "196", "140", "256"], "eh": "a² + b² = (a + b)² − 2ab = 256 − 120 = 136।", "level": "easy"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 1 3/5 + 3 1/2 − 3 5/8", "o": ["99/40", "59/40", "2.95", "137/120"], "a": 1, "e": "Convert to improper fractions: 8/5, 7/2, 29/8. Working step by step gives 59/40.", "qh": "सरल कीजिए: 1 3/5 + 3 1/2 − 3 5/8", "oh": ["99/40", "59/40", "2.95", "137/120"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 8/5, 7/2, 29/8। क्रम से हल करने पर 59/40।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Ravi and Deepak can finish a work in 30 days and 45 days respectively. They work together for 3 days and then Ravi leaves. In how many days in total will the work be finished?", "o": ["18 days", "40.5 days", "37.5 days", "41.5 days"], "a": 1, "e": "In 3 days: 3 × (1/30 + 1/45) = 1/6 done. Left 5/6 is done by Deepak in 37.5 days. Total = 40.5 days.", "qh": "रवि और दीपक एक काम क्रमशः 30 दिन और 45 दिन में पूरा कर सकते हैं। दोनों 3 दिन साथ काम करते हैं और फिर रवि काम छोड़ देता है। काम कुल कितने दिन में पूरा होगा?", "oh": ["18 दिन", "40.5 दिन", "37.5 दिन", "41.5 दिन"], "eh": "3 दिन में: 3 × (1/30 + 1/45) = 1/6 काम हुआ। बचा 5/6 काम अकेले दीपक से 37.5 दिन में होता है। कुल = 40.5 दिन।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "An amount is divided among Rekha, Priya and Ritu in the ratio 2 : 3 : 5. If Ritu gets ₹1,800 more than Rekha, what is Priya's share?", "o": ["₹2,400", "₹1,200", "₹1,800", "₹4,200"], "a": 2, "e": "(5 − 2) parts = ₹1,800 → 1 part = ₹600; Priya = 3 × ₹600 = ₹1,800.", "qh": "एक रकम को रेखा, प्रिया और रितु में 2 : 3 : 5 के अनुपात में बाँटा गया। अगर रितु को रेखा से ₹1,800 ज़्यादा मिलते हैं, तो प्रिया का हिस्सा कितना है?", "oh": ["₹2,400", "₹1,200", "₹1,800", "₹4,200"], "eh": "(5 − 2) भाग = ₹1,800 → 1 भाग = ₹600; प्रिया = 3 × ₹600 = ₹1,800।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Successive discounts of 20%, 40% and 5% are equivalent to a single discount of:", "o": ["64%", "65%", "55.4%", "54.4%"], "a": 3, "e": "Price left = 0.8 × 0.6 × 0.95 = 57/125. Single discount = 54.4%.", "qh": "20%, 40% और 5% की लगातार छूट किस एक छूट के बराबर हैं?", "oh": ["64%", "65%", "55.4%", "54.4%"], "eh": "बचा दाम = 0.8 × 0.6 × 0.95 = 57/125। एक छूट = 54.4%।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "A shopkeeper has some mangoes. If he packs them in boxes of 10, 12 and 15, exactly 4 mangoes are left over every time. What is the least number of mangoes he can have?", "o": ["124", "60", "65", "64"], "a": 3, "e": "LCM(10, 12, 15) = 60; number = 60 + 4 = 64.", "qh": "एक दुकानदार के पास कुछ आम हैं। अगर वह उन्हें 10, 12 और 15 वाले डिब्बों में भरता है, तो हर बार ठीक 4 आम बच जाते हैं। उसके पास कम से कम कितने आम हो सकते हैं?", "oh": ["124", "60", "65", "64"], "eh": "LCM(10, 12, 15) = 60; संख्या = 60 + 4 = 64।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nDG, GJ, JM, MP, ?", "o": ["PS", "QS", "PR", "OS"], "a": 0, "e": "Letter positions move by +3, +3 (for 1st, 2nd letters). So ? = PS.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nDG, GJ, JM, MP, ?", "oh": ["PS", "QS", "PR", "OS"], "eh": "अक्षरों की स्थिति +3, +3 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = PS।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n9, 17, 33, 65, 129, ?", "o": ["259", "262", "260", "257"], "a": 3, "e": "Rule: ×2 then −1. So ? = 257.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n9, 17, 33, 65, 129, ?", "oh": ["259", "262", "260", "257"], "eh": "नियम: ×2 फिर −1। इसलिए ? = 257।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 32 people, Manoj is 8th from the left and Arjun is 8th from the right. How many people are there between them?", "o": ["17", "18", "16", "15"], "a": 2, "e": "Arjun is 25th from the left. Between = 25 − 8 − 1 = 16.", "qh": "32 लोगों की पंक्ति में मनोज बाएँ से 8वें और अर्जुन दाएँ से 8वें स्थान पर है। दोनों के बीच कितने लोग हैं?", "oh": ["17", "18", "16", "15"], "eh": "अर्जुन बाएँ से 25वें स्थान पर है। बीच में = 25 − 8 − 1 = 16।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Suresh starts from point P, walks 6 km towards East, then turns left and walks 15 km, then turns right and walks 3 km. In which direction is Suresh now with respect to point P?", "o": ["South-West", "North-East", "North", "North-West"], "a": 1, "e": "Net East–West = +9 km, net North–South = +15 km; direction = North-East.", "qh": "सुरेश बिंदु P से शुरू करके पूर्व की ओर 6 km चलता है, फिर बाएँ मुड़कर 15 km चलता है, फिर दाएँ मुड़कर 3 km चलता है। अब सुरेश बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पश्चिम", "उत्तर-पूर्व", "उत्तर", "उत्तर-पश्चिम"], "eh": "कुल पूर्व–पश्चिम = +9 km, कुल उत्तर–दक्षिण = +15 km; दिशा = उत्तर-पूर्व।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n10 : 100 :: 11 : ?", "o": ["121", "132", "110", "122"], "a": 0, "e": "Rule: x → x². 10 → 100, so 11 → 121.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n10 : 100 :: 11 : ?", "oh": ["121", "132", "110", "122"], "eh": "नियम: x → x²। 10 → 100, इसलिए 11 → 121।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nCCB, EDC, GED, IFE, ?", "o": ["MGF", "KGF", "KHF", "JGF"], "a": 1, "e": "Letter positions move by +2, +1, +1 (for 1st, 2nd, 3rd letters). So ? = KGF.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nCCB, EDC, GED, IFE, ?", "oh": ["MGF", "KGF", "KHF", "JGF"], "eh": "अक्षरों की स्थिति +2, +1, +1 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = KGF।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Amit starts from point P, walks 4 km towards South, then turns left and walks 7 km, then turns left and walks 7 km, then turns right and walks 6 km. In which direction is Amit now with respect to point P?", "o": ["South-West", "South-East", "North-East", "East"], "a": 2, "e": "Net East–West = +13 km, net North–South = +3 km; direction = North-East.", "qh": "अमित बिंदु P से शुरू करके दक्षिण की ओर 4 km चलता है, फिर बाएँ मुड़कर 7 km चलता है, फिर बाएँ मुड़कर 7 km चलता है, फिर दाएँ मुड़कर 6 km चलता है। अब अमित बिंदु P से किस दिशा में है?", "oh": ["दक्षिण-पश्चिम", "दक्षिण-पूर्व", "उत्तर-पूर्व", "पूर्व"], "eh": "कुल पूर्व–पश्चिम = +13 km, कुल उत्तर–दक्षिण = +3 km; दिशा = उत्तर-पूर्व।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '÷', '−' means '×', '×' means '+', '÷' means '−', then what is the value of the following expression?\n29 × 13 × 11 ÷ 8 = ?", "o": ["55", "45", "90", "42"], "a": 1, "e": "Replace the signs: 29 + 13 + 11 − 8 = 45 (using BODMAS).", "qh": "अगर '+' का मतलब '÷', '−' का मतलब '×', '×' का मतलब '+', '÷' का मतलब '−' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n29 × 13 × 11 ÷ 8 = ?", "oh": ["55", "45", "90", "42"], "eh": "चिह्न बदलें: 29 + 13 + 11 − 8 = 45 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["ABC", "EFG", "DEF", "LNO"], "a": 3, "e": "In ABC, EFG, DEF the gaps are +1, +1; in LNO they are +2, +1.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["ABC", "EFG", "DEF", "LNO"], "eh": "ABC, EFG, DEF में अंतर +1, +1 है; LNO में +2, +1 है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "Pointing to a photograph, a woman said, \"This person is the only daughter of my mother's mother.\" How is the person in the photograph related to the woman?", "o": ["Mother", "Aunt", "Sister", "Grandmother"], "a": 0, "e": "Simplify from the end: 'the only daughter of my mother's mother' points to the woman's mother.", "qh": "एक तस्वीर की ओर इशारा करते हुए एक महिला ने कहा, \"यह व्यक्ति मेरी नानी की इकलौती बेटी है।\" तस्वीर वाला व्यक्ति उस महिला का क्या लगता है?", "oh": ["माँ", "मौसी", "बहन", "नानी"], "eh": "आखिर से सरल करें: 'मेरी नानी की इकलौती बेटी' = माँ।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "E, M, K, R, P, H and J are sitting in a row, all facing North.\nE is not an immediate neighbour of J.\nR sits immediately to the right of E.\nP sits at one of the ends.\nExactly 2 persons sit between M and J.\nM is not an immediate neighbour of P.\nJ and P sit next to each other.\nP sits second to the right of K.\nWho sits exactly in the middle of the row?", "o": ["R", "K", "M", "H"], "a": 3, "e": "Only one order fits all clues (left to right): E R M H K J P. Answer: H.", "qh": "E, M, K, R, P, H और J एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nE, J का ठीक पड़ोसी नहीं है।\nR, E के ठीक दाईं ओर बैठा है।\nP किसी एक छोर पर बैठा है।\nM और J के बीच ठीक 2 व्यक्ति बैठे हैं।\nM, P का ठीक पड़ोसी नहीं है।\nJ और P पास-पास बैठे हैं।\nP, K के दाईं ओर दूसरे स्थान पर बैठा है।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["R", "K", "M", "H"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): E R M H K J P। उत्तर: H।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "5 boxes R, P, W, T and Y are kept one above the other (not necessarily in this order).\nBox T is placed immediately above box R.\nBox Y is neither at the top nor at the bottom.\nBox R is neither at the top nor at the bottom.\nBox P is placed somewhere above box R.\nExactly 1 box is placed between boxes T and P.\nBox T is neither at the top nor at the bottom.\nHow many boxes are placed above box P?", "o": ["0", "3", "1", "2"], "a": 0, "e": "Only one order fits (bottom to top): W R T Y P. Answer: 0.", "qh": "5 डिब्बे R, P, W, T और Y एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बा T, डिब्बे R के ठीक ऊपर रखा है।\nडिब्बा Y न सबसे ऊपर है, न सबसे नीचे।\nडिब्बा R न सबसे ऊपर है, न सबसे नीचे।\nडिब्बा P, डिब्बे R से कहीं ऊपर रखा है।\nडिब्बे T और P के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बा T न सबसे ऊपर है, न सबसे नीचे।\nडिब्बे P के ऊपर कितने डिब्बे रखे हैं?", "oh": ["0", "3", "1", "2"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): W R T Y P। उत्तर: 0।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nRRCW : VNGR :: XVFE : ?", "o": ["ZJRB", "BRJZ", "TZBJ", "BRJA"], "a": 1, "e": "Each letter moves +4, -4, +4, -5 in order. XVFE → BRJZ.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nRRCW : VNGR :: XVFE : ?", "oh": ["ZJRB", "BRJZ", "TZBJ", "BRJA"], "eh": "हर अक्षर क्रम से +4, -4, +4, -5 खिसकता है। XVFE → BRJZ।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "W is the husband of U. U is the mother of N. How is W related to N?", "o": ["Father", "Brother-in-law", "Grandson", "Father-in-law"], "a": 0, "e": "Draw the family tree: W → U: husband; U → N: mother. So W is the father of N.", "qh": "W, U का पति है। U, N की माँ है। W का N से क्या संबंध है?", "oh": ["पिता", "साला/देवर/जीजा", "पोता/नाती", "ससुर"], "eh": "परिवार का चार्ट बनाएँ: W → U: पति; U → N: माँ। इसलिए W, N का पिता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "B, A, L, E and J are sitting around a circular table, all facing the centre.\nA is an immediate neighbour of J.\nA sits immediately to the left of E.\nL sits immediately to the right of E.\nWho sits to the immediate right of J?", "o": ["E", "B", "A", "L"], "a": 2, "e": "Only one arrangement fits. Going to the right (anticlockwise) from J: J → A → E → L → B. Answer: A.", "qh": "B, A, L, E और J एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nA, J का ठीक पड़ोसी है।\nA, E के ठीक बाईं ओर बैठा है।\nL, E के ठीक दाईं ओर बैठा है।\nJ के ठीक दाईं ओर कौन बैठा है?", "oh": ["E", "B", "A", "L"], "eh": "केवल एक व्यवस्था बैठती है। J से दाईं ओर (घड़ी की उलटी दिशा में) चलें: J → A → E → L → B। उत्तर: A।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'PAINT' is coded as 60 and 'DOG' is coded as 26. How will 'TIGER' be coded in that language?", "o": ["64", "60", "57", "59"], "a": 3, "e": "Code = sum of letter positions (A = 1, B = 2, …): PAINT = 16+1+9+14+20 = 60, DOG = 4+15+7 = 26. TIGER = 20+9+7+5+18 = 59.", "qh": "एक कोड भाषा में 'PAINT' को 60 और 'DOG' को 26 लिखा जाता है। उसी भाषा में 'TIGER' को कैसे लिखा जाएगा?", "oh": ["64", "60", "57", "59"], "eh": "कोड = अक्षरों की स्थितियों का योग (A = 1, B = 2, …): PAINT = 16+1+9+14+20 = 60, DOG = 4+15+7 = 26। TIGER = 20+9+7+5+18 = 59।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n423   654   579   624   432\nWhat is the result when the middle digit of the number that is in the middle (after arranging the numbers in ascending order) is added to the difference between the largest and the smallest number?", "o": ["241", "239", "236", "238"], "a": 3, "e": "Ascending: 423, 432, 579, 624, 654. 654 − 423 = 231; middle digit of 579 = 7; total = 238.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n423   654   579   624   432\nसंख्याओं को बढ़ते क्रम में लगाने पर बीच वाली संख्या का बीच का अंक, सबसे बड़ी और सबसे छोटी संख्या के अंतर में जोड़ने पर क्या मिलेगा?", "oh": ["241", "239", "236", "238"], "eh": "बढ़ता क्रम: 423, 432, 579, 624, 654। 654 − 423 = 231; 579 का बीच का अंक = 7; कुल = 238।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nEye : See :: Ear : ?", "o": ["Sound", "Hear", "Nose", "Speak"], "a": 1, "e": "Relation: 'is used to'. Eye – See, so Ear – Hear.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nआँख : देखना :: कान : ?", "oh": ["आवाज़", "सुनना", "नाक", "बोलना"], "eh": "संबंध: 'का काम'। आँख – देखना, इसलिए कान – सुनना।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo pens are tables.\nSome tables are bricks.\nConclusions:\nI. Some pens are not tables.\nII. No tables are pens.", "o": ["Both I and II follow", "Only conclusion I follows", "Neither I nor II follows", "Only conclusion II follows"], "a": 0, "e": "Both conclusions are true in every possible diagram.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी पेन मेज़ें नहीं है।\nकुछ मेज़ें ईंटें हैं।\nनिष्कर्ष:\nI. कुछ पेन मेज़ें नहीं हैं।\nII. कोई भी मेज़ें पेन नहीं है।", "oh": ["I और II दोनों सही हैं", "केवल निष्कर्ष I सही है", "न I सही है, न II", "केवल निष्कर्ष II सही है"], "eh": "दोनों निष्कर्ष हर संभव आरेख में सही हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n18 ÷ 14 − 20 × 2 + 16 = 258", "o": ["− and ×", "+ and ÷", "× and ÷", "+ and −"], "a": 2, "e": "Interchanging × and ÷: 18 × 14 − 20 ÷ 2 + 16 = 258. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n18 ÷ 14 − 20 × 2 + 16 = 258", "oh": ["− और ×", "+ और ÷", "× और ÷", "+ और −"], "eh": "× और ÷ बदलने पर: 18 × 14 − 20 ÷ 2 + 16 = 258। ✔", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nN 9 6 € 7 8 2 + # 6 € M 4 N 4 * A # 4 O # #\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["1", "2", "4", "3"], "a": 0, "e": "Matching places: €78 → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nN 9 6 € 7 8 2 + # 6 € M 4 N 4 * A # 4 O # #\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["1", "2", "4", "3"], "eh": "शर्त पूरी करने वाले स्थान: €78 → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nP Q O I 3 © $ + I # & 7 H M 6 5 6 # F 1 L K\nHow many numbers are there in the arrangement, each of which is immediately preceded by a letter and immediately followed by a symbol?", "o": ["2", "3", "1", "4"], "a": 2, "e": "Matching places: I3© → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nP Q O I 3 © $ + I # & 7 H M 6 5 6 # F 1 L K\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक पहले एक अक्षर और ठीक बाद एक चिह्न है?", "oh": ["2", "3", "1", "4"], "eh": "शर्त पूरी करने वाले स्थान: I3© → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n4 4 1 7 8 7 9 8 8 3 8 3 5 8 7 4 9 6 1 5 2 9 1 5 5\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["5", "4", "2", "1"], "a": 2, "e": "Matching groups: 3 5 8, 1 5 2 → 2.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n4 4 1 7 8 7 9 8 8 3 8 3 5 8 7 4 9 6 1 5 2 9 1 5 5\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["5", "4", "2", "1"], "eh": "शर्त पूरी करने वाले समूह: 3 5 8, 1 5 2 → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Mercury", "Venus", "Mars", "Moon"], "a": 3, "e": "The Moon is a natural satellite; the others are planets.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["बुध", "शुक्र", "मंगल", "चंद्रमा"], "eh": "चंद्रमा उपग्रह है; बाकी ग्रह हैं।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "What is the angle between the hour hand and the minute hand of a clock at 10:40?", "o": ["85°", "80°", "60°", "87.5°"], "a": 1, "e": "Angle = |30H − 5.5M| = |30×10 − 5.5×40| = 80° → smaller angle = 80°.", "qh": "10:40 बजे घड़ी की घंटे और मिनट की सुई के बीच कितना कोण होगा?", "oh": ["85°", "80°", "60°", "87.5°"], "eh": "कोण = |30H − 5.5M| = |30×10 − 5.5×40| = 80° → छोटा कोण = 80°।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Venn Diagram", "q": "In a group of 100 people, 46 like tea, 48 like coffee and 32 like both. How many like exactly one of the two?", "o": ["62", "30", "54", "27"], "a": 1, "e": "Exactly one = (46 − 32) + (48 − 32) = 30.", "qh": "100 लोगों के समूह में 46 को चाय पसंद है, 48 को कॉफ़ी पसंद है और 32 को दोनों पसंद हैं। कितने लोगों को दोनों में से ठीक एक पसंद है?", "oh": ["62", "30", "54", "27"], "eh": "ठीक एक = (46 − 32) + (48 − 32) = 30।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: No bus goes from this stop after 10 p.m.\nConclusions:\nI. A person reaching the stop at 11 p.m. cannot catch a bus from there.\nII. Buses run from this stop before 10 p.m.", "o": ["Only conclusion II follows", "Both I and II follow", "Neither I nor II follows", "Only conclusion I follows"], "a": 3, "e": "After 10 p.m. there is no bus, so I follows. The statement does not tell us about buses before 10 p.m. (II is not certain).", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: रात 10 बजे के बाद इस स्टॉप से कोई बस नहीं जाती।\nनिष्कर्ष:\nI. रात 11 बजे स्टॉप पर पहुँचने वाले को वहाँ से बस नहीं मिलेगी।\nII. रात 10 बजे से पहले इस स्टॉप से बसें चलती हैं।", "oh": ["केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II", "केवल निष्कर्ष I सही है"], "eh": "10 बजे के बाद बस नहीं, इसलिए I सही। 10 बजे से पहले की बात कथन में नहीं (II पक्का नहीं)।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["961", "376", "646", "953"], "a": 3, "e": "In all except 953: digit sum is 16.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["961", "376", "646", "953"], "eh": "953 को छोड़कर सभी में: अंकों का योग 16 है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nE3Z, G6W, I12T, K24Q, ?", "o": ["M50N", "L48M", "M48N", "N48N"], "a": 2, "e": "First letter +2; number: double each time; last letter -3. So ? = M48N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nE3Z, G6W, I12T, K24Q, ?", "oh": ["M50N", "L48M", "M48N", "N48N"], "eh": "पहला अक्षर +2; संख्या: हर बार दोगुना; आखिरी अक्षर -3। इसलिए ? = M48N।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'book cold is' is written as 'ni bo su',\n'water book hot' is written as 'bo ra ze',\n'cold road water' is written as 'mo ze su',\nWhat is the code for 'cold'?", "o": ["bo", "su", "ni", "ze"], "a": 1, "e": "Compare the sentences: common words and common codes match. This gives 'cold' = 'su'.", "qh": "एक कोड भाषा में:\n'book cold is' को 'ni bo su' लिखा जाता है,\n'water book hot' को 'bo ra ze' लिखा जाता है,\n'cold road water' को 'mo ze su' लिखा जाता है,\n'cold' का कोड क्या है?", "oh": ["bo", "su", "ni", "ze"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'cold' = 'su' मिलता है।", "level": "medium"}]});
